import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ButtonTransformProps = Record<string, any>;

const ButtonTransform: React.FC<ButtonTransformProps> = ({
  backgroundColor = "#111111",
  transparentBackground = true,
  durationInSeconds = 5,
  sellText = "SELL",
  buyText = "BUY",
  sellColor = "#e74c3c",
  buyColor = "#2ecc71",
  labelColor = "#ffffff",
  buttonRadius = 20,
  fontSize = 80,
  transitionStartFrame = 90,
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Montserrat"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width } = useVideoConfig();

  // Background handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Phase 1: Entry Spring ---
  const entryScale = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 100,
    },
  });

  // --- Animation Phase 2: Hover (Idle) ---
  // Gentle floating sine wave
  const hoverY = Math.sin(frame / 20) * 10;

  // --- Animation Phase 3: Flip Transition ---
  const transitionProgress = frame - transitionStartFrame;
  
  // Create a 3D flip effect:
  // 0 to 10 frames: Rotate 0 -> 90 degrees (tilting away)
  // 10 to 20 frames: Rotate -90 -> 0 degrees (tilting back from bottom)
  // This simulates a full 180 flip while keeping content readable (not mirrored)
  const flipRotation = interpolate(
    transitionProgress,
    [0, 10, 10.0001, 20],
    [0, 90, -90, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Determine state based on the midpoint of the transition (10 frames in)
  const isSellState = transitionProgress < 10;
  
  const currentText = isSellState ? sellText : buyText;
  const currentButtonColor = isSellState ? sellColor : buyColor;
  
  // Use entry scale directly; the flip handles the transition logic now
  const totalScale = entryScale;

  // Font adjustments
  const currentFontSize = fontSize;
  const paddingX = currentFontSize * 1.5;
  const paddingY = currentFontSize * 0.5;

  return (
    <AbsoluteFill 
      style={{ 
        backgroundColor: bgColor, 
        fontFamily: "Montserrat",
        justifyContent: "center",
        alignItems: "center",
        // Perspective is required for 3D rotation effects
        perspective: "1000px",
      }}
    >
      <div
        style={{
          backgroundColor: currentButtonColor,
          borderRadius: buttonRadius,
          paddingLeft: paddingX,
          paddingRight: paddingX,
          paddingTop: paddingY,
          paddingBottom: paddingY,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          boxShadow: "0 10px 25px rgba(0,0,0,0.3)",
          // Combine hover, scale, and the new flip rotation
          transform: `translateY(${hoverY}px) scale(${totalScale}) rotateX(${flipRotation}deg)`,
          // Ensure no default CSS transitions interfere with frame-based animation
          transition: "none", 
          willChange: "transform, background-color",
          // Helps with 3D rendering smoothness
          transformStyle: "preserve-3d",
        }}
      >
        <span
          style={{
            color: labelColor,
            fontSize: currentFontSize,
            fontWeight: 700,
            letterSpacing: "0.05em",
            textAlign: "center",
            lineHeight: 1,
            // Prevent text selection cursor
            userSelect: "none",
          }}
        >
          {currentText}
        </span>
      </div>
    </AbsoluteFill>
  );
};

export default ButtonTransform;